#include <cstdio>
#include <cstring>
#include <cmath>
#include <cstdlib>
#include <vector>
#include <string>
#include <algorithm>
#include <queue>
#include <stack>
#include <deque>
#include <map>
#include <set>
#include <unordered_map>
#include <unordered_set>
#include <functional>
#include <numeric>
#include <sstream>
#include <iostream>
using namespace std;
int main(){int n;long long need;scanf("%d %lld",&n,&need);
priority_queue<long long,vector<long long>,greater<long long>>pq;
for(int i=0;i<n;++i){long long x;scanf("%lld",&x);pq.push(x);}
int ops=0;
while(pq.size()>=2&&pq.top()<need){
long long x=pq.top();pq.pop();
long long y=pq.top();pq.pop();
pq.push(x+2*y);++ops;}
printf("%d\n",(pq.top()>=need)?ops:-1);return 0;}

